// src/server.ts
import { APIError, createAuthEndpoint } from "better-auth/api";
import { bearer } from "better-auth/plugins";
import { createRemoteJWKSet, jwtVerify } from "jose";
import { z } from "zod/v4";

// src/lib/pkce.ts
class Pkce {
  static CLAIM = "pkce_s256";
  static base64url(bytes) {
    const binary = Array.from(bytes, (byte) => String.fromCharCode(byte)).join("");
    return Pkce.fromBase64(btoa(binary));
  }
  static fromBase64(base64) {
    const unpadded = base64.replaceAll("+", "-").replaceAll("/", "_");
    const padIndex = unpadded.indexOf("=");
    return padIndex === -1 ? unpadded : unpadded.slice(0, padIndex);
  }
  static randomToken() {
    const bytes = new Uint8Array(32);
    crypto.getRandomValues(bytes);
    return Pkce.base64url(bytes);
  }
  static async challengeS256(verifier) {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
    return Pkce.base64url(new Uint8Array(digest));
  }
}

// src/server.ts
var MANAGED_PROVIDER_ID = "runable";
var exchangeBody = z.object({
  token: z.string(),
  codeVerifier: z.string().optional()
});
var claimsSchema = z.object({
  sub: z.string(),
  email: z.string(),
  email_verified: z.boolean().optional(),
  name: z.string().optional(),
  picture: z.string().optional()
});
var runableManagedAuth = (config) => {
  const issuer = config.issuer.endsWith("/") ? config.issuer.slice(0, -1) : config.issuer;
  const jwks = createRemoteJWKSet(new URL(`${issuer}/jwks`));
  const managedExchange = createAuthEndpoint("/managed/exchange", { method: "POST", body: exchangeBody }, async (ctx) => {
    const verified = await jwtVerify(ctx.body.token, jwks, {
      issuer,
      audience: config.applicationId
    }).catch(() => {
      return;
    });
    if (!verified)
      throw new APIError("UNAUTHORIZED", { message: "Invalid managed auth token" });
    const claims = claimsSchema.safeParse(verified.payload);
    if (!claims.success) {
      throw new APIError("UNAUTHORIZED", { message: "Managed auth token missing identity" });
    }
    const { sub, email, email_verified, name, picture } = claims.data;
    const { jti, exp, [Pkce.CLAIM]: pkceChallenge } = verified.payload;
    const { codeVerifier } = ctx.body;
    const pkceBound = typeof pkceChallenge === "string";
    const pkceVerified = !pkceBound || typeof codeVerifier === "string" && await Pkce.challengeS256(codeVerifier) === pkceChallenge;
    if (!pkceVerified) {
      throw new APIError("UNAUTHORIZED", { message: "Managed auth PKCE verification failed" });
    }
    const adapter = ctx.context.internalAdapter;
    if (typeof jti === "string") {
      const expiresAt = typeof exp === "number" ? new Date(exp * 1000) : new Date(Date.now() + 5 * 60 * 1000);
      const reserved = await adapter.reserveVerificationValue({
        identifier: `managed-auth:${jti}`,
        value: "redeemed",
        expiresAt
      });
      if (!reserved) {
        throw new APIError("UNAUTHORIZED", {
          message: "Managed auth token already redeemed"
        });
      }
    }
    const profile = {
      email,
      name: name ?? email,
      image: picture,
      emailVerified: email_verified ?? false
    };
    const linked = await adapter.findAccountByProviderId(sub, MANAGED_PROVIDER_ID);
    const existing = linked ? await adapter.findUserById(linked.userId) : null;
    const user = existing ? await adapter.updateUser(existing.id, profile) : await adapter.createUser(profile);
    if (!existing) {
      await adapter.linkAccount({
        providerId: MANAGED_PROVIDER_ID,
        accountId: sub,
        userId: user.id
      });
    }
    const session = await adapter.createSession(user.id);
    return ctx.json({ token: session.token, user });
  });
  return [
    bearer(),
    {
      id: "runable-managed-auth",
      endpoints: { managedExchange }
    }
  ];
};
export {
  runableManagedAuth
};
